class PaymentError(Exception):
    pass

class CardDeclined(PaymentError):
    pass

class LimitExceeded(PaymentError):
    pass

def pay(amount, limit):
    if amount > limit:
        raise LimitExceeded(amount, limit)
    if amount == 13:
        raise CardDeclined("banka reddetti")
    return "ödendi"

for amount in [50, 13, 900]:
    try:
        print(pay(amount, 500))
    except LimitExceeded as error:
        print("limit:", error.args)
    except PaymentError as error:
        print(type(error).__name__, error)

