def apply_discount(price, percent):
    if not 0 <= percent <= 100:
        raise ValueError(f"indirim 0-100 arası olmalı: {percent}")
    new_price = price * (100 - percent) / 100
    assert 0 <= new_price <= price
    return new_price

print(apply_discount(200, 25))
try:
    apply_discount(200, 150)
except ValueError as error:
    print(error)

